16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.concurrent.atomic.AtomicInteger;
19	
20	import org.slf4j.Logger;
21	import org.slf4j.LoggerFactory;
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Emits the audit records for a newly created owner to the {@code AUDIT} logger: a
26	 * human-readable line and an immutable, structured {@code OWNER_CREATED} event carrying a
27	 * monotonically increasing {@code seq} across all creates, the owner id, and the owner's
28	 * current primary identifier, the {@code memberId}.
29	 */
30	public final class OwnerCreatedEvent {
31	
32	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
33	
34	    private static final AtomicInteger SEQ = new AtomicInteger();
35	
36	    private OwnerCreatedEvent() {
37	    }
38	
39	    public static void emit(Owner owner) {
40	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
41	            owner.getId(), primaryId(owner), owner.getRegistrationDate(), MembershipLevel.of(owner));
42	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
43	            SEQ.incrementAndGet(), owner.getId(), primaryId(owner), owner.getMembershipLevel());
44	        WelcomeNotification.enqueue(owner);
45	    }
46	
47	    private static String primaryId(Owner owner) {
48	        return owner.getMemberId();
49	    }
50	}
